// ── state ──
let avail = {};
P.forEach(function(p,i){ avail[i] = p.ok; });
let prodOverrides = {};
let archived = {};
let deleted = {};
let customProds = [];
let stockQty = {};

function _applyState(d){
  if(d.avail) Object.assign(avail, d.avail);
  if(d.overrides && Object.keys(d.overrides).length){
    prodOverrides = d.overrides;
    Object.keys(prodOverrides).forEach(function(i){ if(P[i]) Object.assign(P[i], prodOverrides[i]); });
  }
  if(d.archived) archived = d.archived;
  if(d.deleted) deleted = d.deleted;
  if(d.custom_prods && d.custom_prods.length){
    customProds = d.custom_prods;
    customProds.forEach(function(p){ P.push(Object.assign({_custom:true},p)); });
  }
  Object.keys(prodOverrides).forEach(function(i){ if(prodOverrides[i] && prodOverrides[i].stock>0) stockQty[i]=prodOverrides[i].stock; });
}

function fmt(n){ return n.toLocaleString('cs-CZ',{minimumFractionDigits:2,maximumFractionDigits:2})+' Kč'; }
function changeQty(i,d){ var el=document.getElementById('q'+i); if(!el) return; var sq=stockQty[i]||0; var nv=Math.max(0,(parseInt(el.value)||0)+d); if(sq>0) nv=Math.min(nv,sq); el.value=nv; recalc(); }

function buildAll(){
  var cats = [];
  P.forEach(function(p,i){ if(!deleted[i]&&!archived[i]&&cats.indexOf(p.cat)<0) cats.push(p.cat); });
  var cont = document.getElementById('pc');
  cont.innerHTML = '';
  var renderedCats = [];
  cats.forEach(function(cat){
    var prods = P.map(function(p,i){ return Object.assign({},p,{idx:i}); })
      .filter(function(p){ return p.cat===cat && !deleted[p.idx] && !archived[p.idx]; });
    if(!prods.length) return;
    renderedCats.push(cat);
    prods.sort(function(a,b){
      var aOk=avail[a.idx]?0:1, bOk=avail[b.idx]?0:1;
      if(aOk!==bOk) return aOk-bOk;
      return a.name.localeCompare(b.name,'cs');
    });
    var nok = prods.filter(function(p){ return avail[p.idx]; }).length;
    var cards = '';
    prods.forEach(function(p){
      var ok = avail[p.idx];
      var warm = p.sklad.indexOf('18')>=0 || p.sklad.indexOf('25')>=0;
      var tagCls = warm ? 'tag-warm' : 'tag-cold';
      var meta = '';
      if(p.baleni) meta += '<span>'+p.baleni+'</span>';
      if(p.trv) meta += '<span>'+p.trv+'</span>';
      cards += '<div class="prod-card'+(ok?'':' unavail')+'">'
        +'<div class="prod-card-name">'+p.name+'</div>'
        +'<div class="prod-card-tags">'
          +'<span class="ptag '+tagCls+'">'+p.sklad+'</span>'
          +(ok?'':'<span class="prod-na-badge">Nedostupné</span>')
        +'</div>'
        +(meta?'<div class="prod-card-meta">'+meta+'</div>':'')
        +(p.vahy
          ? '<div class="prod-card-price">'+p.voc+' Kč<span class="prod-price-per"> / ks</span></div>'
            +'<div class="prod-vahy-sub"><span class="prod-vahy-kg">'+p.voc_kg+' Kč/kg</span><span class="vahy-badge">vážený produkt</span></div>'
          : '<div class="prod-card-price">'+p.voc+' Kč<span class="prod-price-per"> / ks</span></div>')
        +(ok?(function(){
            var sq=stockQty[p.idx]||0;
            var maxAttr=sq>0?' max="'+sq+'"':'';
            var stockBadge=sq>0?'<span style="font-size:11px;font-weight:700;color:#c0522a;background:rgba(192,82,42,.1);border-radius:6px;padding:2px 7px;">Zbývá '+sq+' ks</span>':'';
            return '<div style="display:flex;align-items:center;justify-content:space-between;gap:4px;margin-top:2px;">'+stockBadge+'</div>'
              +'<div class="prod-card-qty-row"><button class="qty-btn" onclick="changeQty('+p.idx+',-1)">−</button><input class="qty-inp" type="number" min="0" step="1" value="0"'+maxAttr+' id="q'+p.idx+'" oninput="recalc()"><button class="qty-btn" onclick="changeQty('+p.idx+',1)">+</button></div>';
          })():'')
        +'<div class="prod-card-total" id="l'+p.idx+'"></div>'
        +'</div>';
    });
    var block = document.createElement('div');
    block.className = 'cat-block';
    block.innerHTML = '<div class="cat-hd"><span class="cat-name">'+cat+'</span><span class="cat-cnt">'+nok+' / '+prods.length+' skladem</span></div>'
      +'<div class="prod-grid">'+cards+'</div>';
    cont.appendChild(block);
  });
  recalc();
  _buildCatNav(renderedCats);
  _watchCatScroll();
}

function _buildCatNav(cats){
  var nav = document.getElementById('cat-nav');
  if(!nav) return;
  nav.innerHTML = cats.map(function(c, i){
    return '<button class="cat-nav-tab" type="button" onclick="_jumpToCat('+i+')">'+_he(c)+'</button>';
  }).join('');
}

function _jumpToCat(i){
  var blocks = document.querySelectorAll('#pc > .cat-block');
  var b = blocks[i];
  if(!b) return;
  var navH = (document.getElementById('cat-nav')||{}).offsetHeight || 0;
  var top = b.getBoundingClientRect().top + window.scrollY - navH - 12;
  window.scrollTo({ top: top, behavior: 'smooth' });
}

function _watchCatScroll(){
  var blocks = document.querySelectorAll('#pc > .cat-block');
  var tabs = document.querySelectorAll('.cat-nav-tab');
  if(!blocks.length || !tabs.length) return;
  var pending = false;
  function update(){
    pending = false;
    var navH = (document.getElementById('cat-nav')||{}).offsetHeight || 0;
    var y = window.scrollY + navH + 24;
    var activeIdx = 0;
    for(var i=0;i<blocks.length;i++){
      if(blocks[i].offsetTop <= y) activeIdx = i; else break;
    }
    for(var j=0;j<tabs.length;j++){
      if(j===activeIdx) tabs[j].classList.add('active');
      else tabs[j].classList.remove('active');
    }
  }
  function onScroll(){
    if(pending) return;
    pending = true;
    requestAnimationFrame(update);
  }
  if(window._dfCatScrollHandler) window.removeEventListener('scroll', window._dfCatScrollHandler);
  window._dfCatScrollHandler = onScroll;
  window.addEventListener('scroll', onScroll, { passive: true });
  update();
}

function recalc(){
  var total = 0, items = [];
  P.forEach(function(p,i){
    var el = document.getElementById('q'+i);
    if(!el) return;
    var q = Math.max(0, parseInt(el.value)||0);
    var lel = document.getElementById('l'+i);
    if(q>0){
      var val = p.voc*q; total+=val;
      if(lel) lel.textContent = fmt(val);
      items.push(Object.assign({},p,{qty:q,total:val}));
    } else { if(lel) lel.textContent='—'; }
  });
  document.getElementById('tv').textContent = fmt(total);
  var dph = total * VAT;
  document.getElementById('tsdph').innerHTML = total>0
    ? '<span>Celkem s DPH: <strong>'+fmt(total*(1+VAT))+'</strong></span>'
    : '';
  // floating bar
  var fb=document.getElementById('float-bar');
  if(fb){
    if(total>0){
      var totalQty=items.reduce(function(s,it){return s+it.qty;},0);
      document.getElementById('float-cnt').textContent=totalQty+' ks';
      document.getElementById('float-amt').textContent=fmt(total);
      fb.classList.add('show');
    } else { fb.classList.remove('show'); }
  }
  var sb = document.getElementById('sb');
  if(!items.length){
    sb.innerHTML='<div class="sum-empty">Zatím nebyl vybrán žádný produkt.</div>';
    return;
  }
  var irows = '';
  items.forEach(function(it){
    var n = it.name+(it.baleni?' ('+it.baleni+')':'');
    irows += '<div class="srow"><span class="sn">'+n+' \u00d7 '+it.qty+' ks</span><span class="sv">'+fmt(it.total)+'</span></div>';
  });
  sb.innerHTML = '<div class="sum-items">'+irows+'</div>'
    +'<div class="sum-sub"><span>DPH 12 %</span><span>'+fmt(dph)+'</span></div>';
}

function potvrditObjednavku(){
  var jm=document.getElementById('jmeno').value.trim();
  var em=document.getElementById('email').value.trim();
  if(!jm||!em){ alert('Vyplňte prosím jméno a e-mail.'); return; }
  var items=[];
  P.forEach(function(p,i){
    var el=document.getElementById('q'+i); if(!el) return;
    var q=Math.max(0,parseInt(el.value)||0);
    if(q>0) items.push(Object.assign({},p,{qty:q,total:p.voc*q}));
  });
  if(!items.length){ alert('Přidejte prosím alespoň jeden produkt.'); return; }
  var tb=items.reduce(function(s,i){return s+i.total;},0);
  var fi=document.getElementById('firma').value.trim();
  var tel=document.getElementById('tel').value.trim();
  var adr=document.getElementById('adr').value.trim();
  var poz=document.getElementById('poz').value.trim();

  var btn=document.querySelector('.send-btn');
  if(btn){ btn.disabled=true; btn.textContent='Odesílám…'; }

  _db.from('orders').insert([{
    customer_name: jm,
    company: fi||null,
    email: em,
    phone: tel||null,
    address: adr||null,
    note: poz||null,
    items: items.map(function(it){ return {name:it.name,baleni:it.baleni||'',qty:it.qty,voc:it.voc,total:it.total}; }),
    total_without_vat: tb,
    user_id: _user ? _user.id : null
  }]).then(function(res){
    if(btn){ btn.disabled=false; btn.textContent='Potvrdit objednávku →'; }
    if(res.error){ alert('Nepodařilo se odeslat objednávku. Zkuste to prosím znovu.\n('+res.error.message+')'); return; }
    // Zapamatovat zákazníka
    saveCustomerDetails(jm,fi,em,tel,adr);
    // Email notifikace
    if(EJS_KEY){
      var itemsTxt=items.map(function(it){ return it.name+(it.baleni?' ('+it.baleni+')':'')+' — '+it.qty+' ks — '+it.total.toFixed(2)+' Kc'; }).join('\n');
      emailjs.send(EJS_SERVICE, EJS_TEMPLATE, {
        customer_name: jm, company: fi||'—', email: em, phone: tel||'—',
        items_text: itemsTxt, total: tb.toFixed(2), note: poz||'—'
      }).catch(function(e){ console.warn('EmailJS:', e); });
    }
    // Zobrazit potvrzení
    var rows='<div class="confirm-row"><span class="cl">Zákazník</span><span class="cv">'+jm+'</span></div>';
    if(fi) rows+='<div class="confirm-row"><span class="cl">Firma</span><span class="cv">'+fi+'</span></div>';
    rows+='<div class="confirm-row"><span class="cl">Položek</span><span class="cv">'+items.length+' '+(items.length===1?'druh':items.length<5?'druhy':'druhů')+'</span></div>';
    rows+='<div class="confirm-row"><span class="cl">Celkem bez DPH</span><span class="cv">'+tb.toLocaleString('cs-CZ',{minimumFractionDigits:2,maximumFractionDigits:2})+' Kč</span></div>';
    document.getElementById('confirm-detail').innerHTML=rows;
    document.getElementById('confirm-modal').className='show';
  });
}

function closeConfirm(){
  document.getElementById('confirm-modal').className='';
  document.getElementById('poz').value='';
  P.forEach(function(p,i){ var el=document.getElementById('q'+i); if(el) el.value=0; });
  // Refill saved customer details if remember-me is on
  try{
    var saved=localStorage.getItem('df_customer');
    if(saved){ var c=JSON.parse(saved); ['jmeno','firma','email','tel','adr'].forEach(function(id){ var el=document.getElementById(id); if(el) el.value=c[id]||''; }); }
    else { ['jmeno','firma','email','tel','adr'].forEach(function(id){ var el=document.getElementById(id); if(el) el.value=''; }); }
  }catch(e){}
  recalc();
}

function toggleRemember(){
  var on=document.getElementById('remember-me').checked;
  document.getElementById('forget-link').style.display=on?'inline':'none';
  if(!on) localStorage.removeItem('df_customer');
}
function saveCustomerDetails(jm,fi,em,tel,adr){
  if(!document.getElementById('remember-me').checked) return;
  try{ localStorage.setItem('df_customer',JSON.stringify({jmeno:jm,firma:fi,email:em,tel:tel,adr:adr})); }catch(e){}
}
function forgetMe(){
  localStorage.removeItem('df_customer');
  document.getElementById('remember-me').checked=false;
  document.getElementById('forget-link').style.display='none';
}

function odeslat(){
  var jm = document.getElementById('jmeno').value.trim();
  var em = document.getElementById('email').value.trim();
  if(!jm||!em){ alert('Vyplňte prosím jméno a e-mail.'); return; }
  var items=[];
  P.forEach(function(p,i){
    var el=document.getElementById('q'+i); if(!el) return;
    var q=Math.max(0,parseInt(el.value)||0);
    if(q>0) items.push(Object.assign({},p,{qty:q,total:p.voc*q}));
  });
  if(!items.length){ alert('Přidejte prosím alespoň jeden produkt.'); return; }

  // generate & download PDF first
  generatePDF();

  var tb=items.reduce(function(s,i){return s+i.total;},0);
  var datum=new Date().toLocaleDateString('cs-CZ');
  var fi=document.getElementById('firma').value.trim();
  var tel=document.getElementById('tel').value.trim();
  var adr=document.getElementById('adr').value.trim();
  var poz=document.getElementById('poz').value.trim();
  // Uložit do Supabase
  _db.from('orders').insert([{
    customer_name: jm,
    company: fi||null,
    email: em,
    phone: tel||null,
    address: adr||null,
    note: poz||null,
    items: items.map(function(it){ return {name:it.name,baleni:it.baleni||'',qty:it.qty,voc:it.voc,total:it.total}; }),
    total_without_vat: tb,
    user_id: _user ? _user.id : null
  }]).then(function(res){ if(res.error) console.warn('Supabase insert error:', res.error.message); });

  var subj='Objednávka – '+jm+(fi?' / '+fi:'')+' – '+datum;
  var body='OBJEDNÁVKA – DIVOKÉ FARMY\n';
  body+='══════════════════════════════\n';
  body+='Datum: '+datum+'\n';
  body+='Zákazník: '+jm+'\n';
  if(fi) body+='Firma: '+fi+'\n';
  body+='E-mail: '+em+'\n';
  if(tel) body+='Telefon: '+tel+'\n';
  if(adr) body+='Adresa: '+adr+'\n';
  body+='\nOBJEDNANÉ ZBOŽÍ:\n';
  body+='──────────────────────────────\n';
  items.forEach(function(it){
    body+=it.name+(it.baleni?' ('+it.baleni+')':'')+'\n';
    body+='  Množství: '+it.qty+' ks  |  VOC/ks: '+it.voc+' Kč  |  Celkem: '+it.total.toFixed(2)+' Kč\n';
  });
  body+='──────────────────────────────\n';
  body+='Celkem bez DPH: '+tb.toFixed(2)+' Kč\n';
  body+='DPH 12 %:       '+(tb*VAT).toFixed(2)+' Kč\n';
  body+='Celkem s DPH:   '+(tb*(1+VAT)).toFixed(2)+' Kč\n';
  if(poz) body+='\nPoznámka: '+poz+'\n';
  body+='\n* Cena orientační, skutečná cena u váženého zboží bude upřesněna.';
  setTimeout(function(){
    window.location.href='mailto:'+EMAIL_TO+'?subject='+encodeURIComponent(subj)+'&body='+encodeURIComponent(body);
    setTimeout(function(){ showPdfNotice(); }, 800);
  }, 400);
}

function showPdfNotice(){
  var n=document.getElementById('pdf-notice');
  if(!n) return;
  n.style.display='flex';
  setTimeout(function(){ n.style.opacity='1'; },10);
  setTimeout(function(){ n.style.opacity='0'; setTimeout(function(){n.style.display='none';},400); },6000);
}

// PASSWORD
// ── Admin access (Supabase Auth + RLS) ──
// The UI gate below is UX only. Real protection lives in Supabase RLS:
// the `is_admin()` policies refuse non-admin writes even if a user opens
// the admin overlay via DevTools. See supabase/migrations/01_admin_rls.sql.
var _adminPendingOpen = false;
function _isAdmin(){
  return !!(_user && _user.app_metadata && _user.app_metadata.role === 'admin');
}
function requestAdminAccess(){
  if(_isAdmin()){ openAdmin(); return; }
  if(_user){
    alert('Tento účet nemá administrátorská oprávnění.\nPřihlaste se prosím účtem správce.');
    return;
  }
  _adminPendingOpen = true;
  openAuthModal('login');
}

// ── ADMIN ──
function openAdmin(){
  switchTab('products');
  renderAdmin('');
  document.getElementById('adm-ov').style.display='block';
}
function closeAdmin(){ document.getElementById('adm-ov').style.display='none'; }

function switchTab(tab){
  ['products','orders','dl'].forEach(function(t){
    var btn=document.getElementById('tab-'+t);
    var pane=document.getElementById('pane-'+t);
    if(btn) btn.classList.toggle('active', t===tab);
    if(pane) pane.style.display = t===tab ? 'block' : 'none';
  });
  if(tab==='orders') loadOrders();
  if(tab==='dl') loadDodaciListy();
}

// ── Orders ──
var _orders = [];
function loadOrders(){
  document.getElementById('orders-list').innerHTML = '<div class="orders-msg">Načítám objednávky…</div>';
  _db.from('orders').select('*').order('created_at',{ascending:false}).then(function(res){
    if(res.error){ document.getElementById('orders-list').innerHTML='<div class="orders-msg">Chyba: '+res.error.message+'</div>'; return; }
    _orders = res.data || [];
    renderOrders();
  });
}

function renderOrders(){
  var list = document.getElementById('orders-list');
  if(!_orders.length){ list.innerHTML='<div class="orders-msg">Zatím žádné objednávky.</div>'; return; }
  var stLabel={nova:'Nová',vyrizuje_se:'Vyřizuje se',vyrizena:'Vyřízena',storno:'Storno',archivovana:'Archivováno'};
  var stCls={nova:'st-nova',vyrizuje_se:'st-vyrizuje',vyrizena:'st-vyrizena',storno:'st-storno',archivovana:'st-archivovana'};
  var html='<div class="orders-list">';
  _orders.forEach(function(o,idx){
    var d=new Date(o.created_at).toLocaleDateString('cs-CZ');
    var st=o.status||'nova';
    var items=o.items||[];
    var irows='';
    items.forEach(function(it){
      irows+='<tr><td>'+(it.name||'')+(it.baleni?' ('+it.baleni+')':'')+'</td><td style="text-align:center">'+it.qty+' ks</td><td style="text-align:right;font-weight:800">'+it.total.toFixed(2)+' Kč</td></tr>';
    });
    var info='';
    if(o.company) info+='<strong>'+o.company+'</strong> · ';
    info+=o.email;
    if(o.phone) info+=' · '+o.phone;
    if(o.address) info+='<br>'+o.address;
    if(o.note) info+='<br><em>'+o.note+'</em>';
    var isStorno = st==='storno';
    html+='<div class="order-card'+(isStorno?' storno-card':'')+'" id="oc'+idx+'">'
      +'<div class="order-hd" onclick="toggleOrder('+idx+')">'
        +'<span class="order-date">'+d+'</span>'
        +'<span class="order-name">'+o.customer_name+(o.company?'<br><small style="font-size:11px;font-weight:500;opacity:.65;letter-spacing:0">'+o.company+'</small>':'')+'</span>'
        +'<span class="order-total">'+o.total_without_vat.toFixed(2)+' Kč</span>'
        +'<span class="order-status '+(stCls[st]||'st-nova')+'" id="ostlbl'+idx+'">'+(stLabel[st]||'Nová')+'</span>'
      +'</div>'
      +'<div class="order-body" id="ob'+idx+'">'
        +'<div class="order-info">'+info+'</div>'
        +'<table class="order-items-tbl"><tr><th>Produkt</th><th style="text-align:center">Množství</th><th style="text-align:right">Celkem</th></tr>'+irows+'</table>'
        +'<div class="order-actions">'
          +'<button class="st-btn'+(st==='nova'?' act':'')+'" onclick="setOrderStatus(\''+o.id+'\','+idx+',\'nova\')">Nová</button>'
          +'<button class="st-btn'+(st==='vyrizuje_se'?' act':'')+'" onclick="setOrderStatus(\''+o.id+'\','+idx+',\'vyrizuje_se\')">Vyřizuje se</button>'
          +'<button class="st-btn'+(st==='vyrizena'?' act':'')+'" onclick="setOrderStatus(\''+o.id+'\','+idx+',\'vyrizena\')">Vyřízena</button>'
          +'<button class="order-pdf-btn" onclick="tiskniObjednavkuPDF('+idx+')">🖨 PDF</button>'
          +'<button class="dl-make-btn" onclick="openDodaciList('+idx+')">📄 Dodací list</button>'
          +'<button class="danger-btn" onclick="stornujObjednavku(\''+o.id+'\','+idx+')">⊘ Storno</button>'
          +'<button class="muted-btn" onclick="archivujObjednavku(\''+o.id+'\','+idx+')">📦 Archivovat</button>'
          +'<button class="danger-btn" style="border-color:rgba(100,0,0,0.3);background:rgba(100,0,0,0.07);color:#800" onclick="smazatObjednavku(\''+o.id+'\','+idx+')">🗑 Smazat</button>'
        +'</div>'
      +'</div>'
    +'</div>';
  });
  html+='</div>';
  list.innerHTML=html;
}

function toggleOrder(idx){
  document.getElementById('ob'+idx).classList.toggle('show');
}

function setOrderStatus(id,idx,status){
  var stLabel={nova:'Nová',vyrizuje_se:'Vyřizuje se',vyrizena:'Vyřízena',storno:'Storno',archivovana:'Archivováno'};
  var stCls={nova:'st-nova',vyrizuje_se:'st-vyrizuje',vyrizena:'st-vyrizena',storno:'st-storno',archivovana:'st-archivovana'};
  _db.from('orders').update({status:status}).eq('id',id).then(function(res){
    if(res.error){ alert('Chyba při ukládání stavu: '+res.error.message+'\n\nSpusť v Supabase SQL Editor:\nCREATE POLICY "admin_update_orders" ON orders FOR UPDATE TO authenticated USING (true) WITH CHECK (true);'); return; }
    _orders[idx].status=status;
    var lbl=document.getElementById('ostlbl'+idx);
    if(lbl){ lbl.textContent=stLabel[status]; lbl.className='order-status '+(stCls[status]||'st-nova'); }
    var card=document.getElementById('oc'+idx);
    if(card){
      var btns=card.querySelectorAll('.st-btn');
      var sts=['nova','vyrizuje_se','vyrizena'];
      btns.forEach(function(btn,bi){ btn.classList.toggle('act',sts[bi]===status); });
    }
  });
}
function stornujObjednavku(id,idx){
  if(!confirm('Opravdu stornovat tuto objednávku?')) return;
  _db.from('orders').update({status:'storno'}).eq('id',id).then(function(res){
    if(res.error){ alert('Chyba: '+res.error.message); return; }
    _orders[idx].status='storno';
    renderOrders();
  });
}
function archivujObjednavku(id,idx){
  _db.from('orders').update({status:'archivovana'}).eq('id',id).then(function(res){
    if(res.error){ alert('Chyba: '+res.error.message); return; }
    _orders[idx].status='archivovana';
    renderOrders();
  });
}
function smazatObjednavku(id,idx){
  if(!confirm('Opravdu trvale smazat tuto objednávku? Tato akce je nevratná.')) return;
  _db.from('orders').delete().eq('id',id).then(function(res){
    if(res.error){ alert('Chyba při mazání: '+res.error.message+'\n\nPokud se objednávka vrátí po obnovení, spusť v Supabase SQL Editor:\nCREATE POLICY "admin_delete_orders" ON orders FOR DELETE TO authenticated USING (true);'); return; }
    _orders=_orders.filter(function(o){ return o.id!==id; });
    renderOrders();
  });
}
