function saveAdmin(keepOpen){
  _saveProductState();
  if(!keepOpen){ closeAdmin(); }
}

function renderAdmin(q){
  var cats=[];
  P.forEach(function(p,i){ if(!deleted[i]&&cats.indexOf(p.cat)<0) cats.push(p.cat); });
  var html='', ql=q.toLowerCase();
  cats.forEach(function(cat){
    var prods=P.map(function(p,i){return Object.assign({},p,{idx:i});})
      .filter(function(p){ return p.cat===cat&&!deleted[p.idx]&&(!ql||p.name.toLowerCase().indexOf(ql)>=0); });
    if(!prods.length) return;
    html+='<div class="adm-cat"><div class="adm-clabel">'+cat+'</div>';
    prods.forEach(function(p){
      var i=p.idx, ok=!!avail[i], isArch=!!archived[i];
      var esc=function(v){return (v||'').replace(/"/g,'&quot;');};
      html+='<div class="adm-item">'
        +'<div class="adm-row'+(isArch?' archived-row':'')+'" id="admrow'+i+'">'
          +'<span class="adm-pname" id="admpn'+i+'">'+p.name+(isArch?' <em style="font-size:10px;opacity:.6">(archiv)</em>':'')+'</span>'
          +'<span class="adm-bal" id="admbl'+i+'">'+(p.baleni||'')+'</span>'
          +(isArch
            ?'<span class="apill ap-arch">Archivováno</span>'
            :'<span class="apill '+(ok?'ap-ok':'ap-no')+'" id="ap'+i+'">'+(ok?'Skladem':'Nedostupné')+'</span>'
              +(stockQty[i]>0?'<span class="adm-stock-badge" id="admsb'+i+'">Zbývá '+stockQty[i]+' ks</span>':'<span class="adm-stock-badge" id="admsb'+i+'" style="display:none"></span>')
              +'<label class="tgl"><input type="checkbox" '+(ok?'checked':'')+' onchange="tog('+i+',this.checked)"><span class="tsl"></span></label>'
          )
          +'<div class="adm-item-actions">'
            +'<button class="adm-edit-btn" id="admbtn'+i+'" onclick="toggleEdit('+i+')">✎ Upravit</button>'
            +'<button class="adm-arch-btn" onclick="archiveProd('+i+')">'+(isArch?'Obnovit':'Archivovat')+'</button>'
            +'<button class="adm-del-btn" onclick="deleteProd('+i+')">Smazat</button>'
          +'</div>'
        +'</div>'
        +'<div class="adm-edit" id="admedit'+i+'">'
          +'<div class="adm-edit-grid">'
            +'<div class="adm-ef full"><label>Název produktu</label><input id="adn'+i+'" value="'+esc(p.name)+'"></div>'
            +'<div class="adm-ef"><label>VOC cena za kus (Kč bez DPH)</label><input type="number" id="adv'+i+'" value="'+p.voc+'"></div>'
            +'<div class="adm-ef"><label>Balení / Objem</label><input id="adb'+i+'" value="'+esc(p.baleni)+'"></div>'
            +'<div class="adm-ef"><label>Skladování</label><input id="ads'+i+'" value="'+esc(p.sklad)+'"></div>'
            +'<div class="adm-ef"><label>Trvanlivost</label><input id="adt'+i+'" value="'+esc(p.trv)+'"></div>'
            +'<div class="adm-ef"><label>Počet kusů skladem <span style="font-weight:400;font-size:11px;opacity:.65">(0 = neomezeno)</span></label><input type="number" id="adstock'+i+'" min="0" value="'+(stockQty[i]||0)+'"></div>'
            +'<div class="adm-ef adm-vahy-row"><label class="adm-vahy-label"><input type="checkbox" id="advahy'+i+'" '+(p.vahy?'checked':'')+' onchange="toggleVahyKg('+i+',this.checked)"> Vážený produkt (fakturace dle kg)</label></div>'
            +'<div class="adm-ef" style="'+(p.vahy?'':'display:none')+'" id="advefdlkg'+i+'"><label>VOC cena za kg (Kč/kg bez DPH)</label><input type="number" id="advkg'+i+'" value="'+(p.voc_kg||0)+'"></div>'
          +'</div>'
          +'<button class="adm-prod-save" onclick="saveProd('+i+')">Uložit změny</button>'
        +'</div>'
        +'</div>';
    });
    html+='</div>';
  });
  document.getElementById('adm-list').innerHTML=html||'<p style="color:#837261;font-size:13px;padding:10px 0;">Nic nenalezeno.</p>';
}

function tog(i,v){
  avail[i]=v;
  var el=document.getElementById('ap'+i);
  if(el){el.textContent=v?'Skladem':'Nedostupné';el.className='apill '+(v?'ap-ok':'ap-no');}
  _saveProductState();
}
function _saveProductState(){
  var customs=P.filter(function(p){return p._custom;}).map(function(p){
    return {cat:p.cat,name:p.name,baleni:p.baleni,sklad:p.sklad,trv:p.trv,voc:p.voc,ok:p.ok};
  });
  try{
    localStorage.setItem('df_av',JSON.stringify(avail));
    localStorage.setItem('df_po',JSON.stringify(prodOverrides));
    localStorage.setItem('df_arch',JSON.stringify(archived));
    localStorage.setItem('df_del',JSON.stringify(deleted));
    localStorage.setItem('df_cp',JSON.stringify(customs));
    localStorage.setItem('df_sq',JSON.stringify(stockQty));
  }catch(e){}
  _db.from('product_state').upsert([{
    id:1, avail:avail, overrides:prodOverrides, archived:archived, deleted:deleted,
    custom_prods:customs, updated_at:new Date().toISOString()
  }]).then(function(res){ if(res.error) console.warn('Product sync error:',res.error.message); });
  buildAll();
}
function toggleEdit(i){
  var edit=document.getElementById('admedit'+i),btn=document.getElementById('admbtn'+i),row=document.getElementById('admrow'+i);
  var open=edit.classList.contains('show');
  edit.classList.toggle('show',!open);
  btn.classList.toggle('open',!open);
  btn.textContent=open?'✎ Upravit':'✕ Zavřít';
  row.style.borderRadius=open?'12px':'12px 12px 0 0';
}
function toggleVahyKg(i, checked){
  var el=document.getElementById('advefdlkg'+i);
  if(el) el.style.display=checked?'':'none';
}
function saveProd(i){
  var name=document.getElementById('adn'+i).value.trim()||P[i].name;
  var voc=parseFloat(document.getElementById('adv'+i).value)||P[i].voc;
  var baleni=document.getElementById('adb'+i).value.trim();
  var sklad=document.getElementById('ads'+i).value.trim();
  var trv=document.getElementById('adt'+i).value.trim();
  var vahyEl=document.getElementById('advahy'+i);
  var vahy=vahyEl?vahyEl.checked:P[i].vahy;
  var voc_kg=parseFloat(document.getElementById('advkg'+i).value)||0;
  var stockEl=document.getElementById('adstock'+i);
  var stock=stockEl?Math.max(0,parseInt(stockEl.value)||0):0;
  P[i].name=name;P[i].voc=voc;P[i].baleni=baleni;P[i].sklad=sklad;P[i].trv=trv;P[i].vahy=vahy;P[i].voc_kg=voc_kg;
  prodOverrides[i]={name:name,voc:voc,baleni:baleni,sklad:sklad,trv:trv,vahy:vahy,voc_kg:voc_kg,stock:stock};
  if(stock>0){ stockQty[i]=stock; } else { delete stockQty[i]; }
  var pn=document.getElementById('admpn'+i);if(pn)pn.textContent=name;
  var bl=document.getElementById('admbl'+i);if(bl)bl.textContent=baleni;
  toggleEdit(i);
}
function archiveProd(i){
  archived[i]=!archived[i];
  renderAdmin(document.getElementById('adm-srch').value);
}
function deleteProd(i){
  if(!confirm('Opravdu smazat produkt "'+P[i].name+'"? Tuto akci nelze vrátit zpět.')) return;
  deleted[i]=true;
  renderAdmin(document.getElementById('adm-srch').value);
}
function toggleAddForm(){
  var f=document.getElementById('adm-add-form');
  f.classList.toggle('show');
  if(f.classList.contains('show')){
    document.getElementById('anew-name').focus();
  } else {
    ['anew-name','anew-voc','anew-baleni','anew-sklad','anew-trv','anew-voc-kg'].forEach(function(id){
      var el=document.getElementById(id);if(el)el.value='';
    });
    document.getElementById('anew-cat').value='';
    var vahyEl=document.getElementById('anew-vahy');if(vahyEl)vahyEl.checked=false;
    var kgRow=document.getElementById('anew-voc-kg-row');if(kgRow)kgRow.style.display='none';
  }
}
function addProd(){
  var name=document.getElementById('anew-name').value.trim();
  var cat=document.getElementById('anew-cat').value;
  var voc=parseFloat(document.getElementById('anew-voc').value)||0;
  var baleni=document.getElementById('anew-baleni').value.trim();
  var sklad=document.getElementById('anew-sklad').value.trim();
  var trv=document.getElementById('anew-trv').value.trim();
  var vahyEl=document.getElementById('anew-vahy');
  var vahy=vahyEl?vahyEl.checked:false;
  var voc_kg=parseFloat(document.getElementById('anew-voc-kg').value)||0;
  if(!name||!cat||!voc){alert('Vyplňte prosím název, kategorii a cenu.');return;}
  var np={cat:cat,name:name,baleni:baleni,sklad:sklad||'lednice',trv:trv,voc:voc,ok:true,_custom:true,vahy:vahy,voc_kg:voc_kg};
  P.push(np);
  customProds.push(np);
  avail[P.length-1]=true;
  toggleAddForm();
  renderAdmin(document.getElementById('adm-srch').value);
}
document.getElementById('adm-srch').addEventListener('input',function(){renderAdmin(this.value);});

// ── PDF ──
function generatePDF(){
  var jm=document.getElementById('jmeno').value.trim();
  var em=document.getElementById('email').value.trim();
  if(!jm||!em){alert('Vyplňte prosím jméno a e-mail.');return;}
  var items=[];
  P.forEach(function(p,i){
    var el=document.getElementById('q'+i);if(!el)return;
    var q=Math.max(0,parseInt(el.value)||0);
    if(q>0)items.push(Object.assign({},p,{qty:q,total:p.voc*q}));
  });
  if(!items.length){alert('Přidejte prosím alespoň jeden produkt.');return;}
  var tb=items.reduce(function(s,it){return s+it.total;},0);
  var datum=new Date().toLocaleDateString('cs-CZ');
  var fi=document.getElementById('firma').value.trim();
  var tel=document.getElementById('tel').value.trim();
  var adr=document.getElementById('adr').value.trim();
  var poz=document.getElementById('poz').value.trim();

  var {jsPDF}=window.jspdf;
  var doc=new jsPDF({orientation:'portrait',unit:'mm',format:'a4'});

  // header bar
  doc.setFillColor(80,63,55);
  doc.rect(0,0,210,22,'F');
  doc.setTextColor(220,203,188);
  doc.setFontSize(14);doc.setFont('helvetica','bold');
  doc.text('DIVOKE FARMY',14,14);
  doc.setFontSize(9);doc.setFont('helvetica','normal');
  doc.text('Objednavka  |  '+datum,14,20);
  doc.text('DF obchodni s.r.o.  |  adam@divokefarmy.cz  |  +420 777 186 246',210-14,20,{align:'right'});

  // customer block
  doc.setTextColor(30,30,30);
  var y=32;
  doc.setFontSize(9);doc.setFont('helvetica','bold');
  doc.text('ZAKAZNIK',14,y);
  doc.setDrawColor(131,114,97);doc.setLineWidth(0.3);doc.line(14,y+2,90,y+2);
  y+=7;
  doc.setFont('helvetica','normal');
  var info=[jm];
  if(fi)info.push(fi);
  info.push('E-mail: '+em);
  if(tel)info.push('Telefon: '+tel);
  if(adr)info.push('Adresa: '+adr);
  info.forEach(function(l){doc.text(l,14,y);y+=5;});

  y+=4;
  // products table
  doc.autoTable({
    startY:y,
    head:[['Produkt','Objem','Trvanlivost','Skladovani','Mnozstvi','VOC/ks','Celkem']],
    body:items.map(function(it){return[
      it.name,
      it.baleni||'—',
      it.trv||'—',
      it.sklad||'—',
      it.qty+' ks',
      it.voc+' Kc',
      it.total.toFixed(2)+' Kc'
    ];}),
    headStyles:{fillColor:[80,63,55],textColor:[220,203,188],fontStyle:'bold',fontSize:8},
    bodyStyles:{fontSize:8,textColor:[30,30,30]},
    alternateRowStyles:{fillColor:[240,235,228]},
    columnStyles:{0:{cellWidth:55},4:{halign:'center'},5:{halign:'right'},6:{halign:'right',fontStyle:'bold'}},
    margin:{left:14,right:14},
    styles:{lineColor:[200,188,175],lineWidth:0.2}
  });

  var fy=doc.lastAutoTable.finalY+6;
  // totals
  doc.setFillColor(218,203,188);
  doc.rect(14,fy,182,22,'F');
  doc.setFontSize(9);doc.setFont('helvetica','normal');doc.setTextColor(131,114,97);
  doc.text('Celkem bez DPH:',120,fy+7);
  doc.text('DPH 12 %:',120,fy+13);
  doc.setFont('helvetica','bold');doc.setTextColor(30,30,30);
  doc.text(tb.toFixed(2)+' Kc',196,fy+7,{align:'right'});
  doc.text((tb*VAT).toFixed(2)+' Kc',196,fy+13,{align:'right'});
  doc.setFontSize(11);
  doc.text('CELKEM S DPH:',120,fy+21);
  doc.text((tb*(1+VAT)).toFixed(2)+' Kc',196,fy+21,{align:'right'});

  if(poz){
    var py=fy+30;
    doc.setFontSize(8);doc.setFont('helvetica','italic');doc.setTextColor(131,114,97);
    doc.text('Poznamka: '+poz,14,py,{maxWidth:182});
  }

  // footer
  doc.setFillColor(80,63,55);
  doc.rect(0,285,210,12,'F');
  doc.setFontSize(7.5);doc.setFont('helvetica','normal');doc.setTextColor(220,203,188);
  doc.text('DF obchodni s.r.o.  |  ICO: 29279313  |  Sebrov 195, 679 22 Lipuvka  |  divokefarmy.cz',105,292,{align:'center'});
  doc.text('* Cena orientacni, skutecna cena u vazeneho zbozi bude upresnena.',105,296,{align:'center'});

  var fn='objednavka-divokefarmy-'+datum.replace(/\.\s*/g,'-').replace(/-$/,'')+'.pdf';
  doc.save(fn);
}

// ── Dodací listy ──
var _dlItems=[], _dlOrder=null, _dlEditId=null, _dlSaved=false;

var _dlCatActive='', _dlCatQty={};

function _fillDLKatalog(){
  _dlCatQty={};
  var cats=[];
  P.forEach(function(p,i){ if(!deleted[i]&&!archived[i]&&cats.indexOf(p.cat)<0) cats.push(p.cat); });
  if(!_dlCatActive||cats.indexOf(_dlCatActive)<0) _dlCatActive=cats[0]||'';
  // tabs
  var tabsEl=document.getElementById('dl-cat-tabs');
  if(!tabsEl) return;
  tabsEl.innerHTML='';
  cats.forEach(function(cat){
    var btn=document.createElement('button');
    btn.className='dl-cat-tab'+(cat===_dlCatActive?' active':'');
    btn.textContent=cat;
    btn.onclick=function(){ _dlCatActive=cat; _renderDLCatGrid(); document.querySelectorAll('.dl-cat-tab').forEach(function(b){b.classList.toggle('active',b.textContent===cat);}); };
    tabsEl.appendChild(btn);
  });
  _renderDLCatGrid();
}

function _renderDLCatGrid(){
  var grid=document.getElementById('dl-prod-grid');
  if(!grid) return;
  var prods=P.map(function(p,i){return Object.assign({},p,{idx:i});})
    .filter(function(p){return p.cat===_dlCatActive&&!deleted[p.idx]&&!archived[p.idx];});
  prods.sort(function(a,b){
    var aOk=avail[a.idx]?0:1,bOk=avail[b.idx]?0:1;
    if(aOk!==bOk) return aOk-bOk;
    return a.name.localeCompare(b.name,'cs');
  });
  grid.innerHTML='';
  prods.forEach(function(p){
    var ok=avail[p.idx];
    var q=_dlCatQty[p.idx]||0;
    var priceHtml=p.vahy
      ? p.voc_kg+' Kč<span> / kg</span><span class="vahy-badge" style="font-size:9px;margin-left:5px">vážený</span>'
      : p.voc+' Kč<span> / ks</span>';
    var card=document.createElement('div');
    card.className='dl-prod-card'+(ok?'':' unavail');
    card.id='dlcc'+p.idx;
    card.innerHTML='<div class="dl-prod-card-name">'+p.name+'</div>'
      +(p.baleni?'<div style="font-size:10px;color:#837261">'+p.baleni+'</div>':'' )
      +'<div class="dl-prod-card-price">'+priceHtml+'</div>'
      +'<div class="dl-prod-qty-row">'
        +'<button onclick="dlCatQty('+p.idx+',-1)">−</button>'
        +'<input type="number" min="0" value="'+q+'" id="dlcq'+p.idx+'" oninput="_dlCatQty['+p.idx+']=parseInt(this.value)||0;dlCatHighlight('+p.idx+')">'
        +'<button onclick="dlCatQty('+p.idx+',1)">+</button>'
      +'</div>';
    grid.appendChild(card);
  });
}

function dlCatQty(idx,d){
  _dlCatQty[idx]=Math.max(0,(_dlCatQty[idx]||0)+d);
  var inp=document.getElementById('dlcq'+idx); if(inp) inp.value=_dlCatQty[idx];
  dlCatHighlight(idx);
}
function dlCatHighlight(idx){
  var card=document.getElementById('dlcc'+idx);
  if(card) card.style.borderColor=(_dlCatQty[idx]>0)?'#4a7a30':'';
}

function dlPridatVybrane(){
  var added=0;
  Object.keys(_dlCatQty).forEach(function(i){
    var q=_dlCatQty[i]; if(!q) return;
    var p=P[parseInt(i)]; if(!p) return;
    var existing=_dlItems.find(function(it){return it.name===p.name;});
    if(existing){ existing.qty=(existing.qty||0)+q; }
    else { _dlItems.push({name:p.name,baleni:p.baleni||'',qty:q,voc:p.voc,vahy:p.vahy||false,voc_kg:p.voc_kg||0,vahy_kg:0,total:p.voc*q}); }
    added++;
  });
  if(!added){ alert('Nejsou vybrány žádné produkty.'); return; }
  _dlCatQty={};
  _renderDLCatGrid();
  renderDLItems();
}

function _openDLOverlay(){
  _dlCatQty={};
  _fillDLKatalog();
  document.getElementById('dl-note').value='';
  renderDLItems();
  document.getElementById('dl-ov').style.display='block';
}

function openDodaciList(idx){
  _dlOrder=_orders[idx];
  _dlItems=(_dlOrder.items||[]).map(function(it){
    var match=P.find(function(p){return p.name===it.name;});
    var vahy=match?match.vahy:false;
    var voc_kg=match?match.voc_kg:0;
    return Object.assign({},it,{vahy:vahy,voc_kg:voc_kg,vahy_kg:0});
  });
  document.getElementById('dl-f-name').value=_dlOrder.customer_name||'';
  document.getElementById('dl-f-company').value=_dlOrder.company||'';
  document.getElementById('dl-f-ico').value=_dlOrder.ico||'';
  document.getElementById('dl-f-email').value=_dlOrder.email||'';
  document.getElementById('dl-f-phone').value=_dlOrder.phone||'';
  _openDLOverlay();
}

var _contacts=[];
function loadContacts(){ try{ _contacts=JSON.parse(localStorage.getItem('df_contacts')||'[]'); }catch(e){ _contacts=[]; } }
function saveContacts(){ try{ localStorage.setItem('df_contacts',JSON.stringify(_contacts)); }catch(e){} }
function dlAdresarSearch(val){
  var drop=document.getElementById('dl-adresar-drop'); if(!drop) return;
  if(!val||!val.trim()){ drop.style.display='none'; drop.innerHTML=''; return; }
  var q=val.toLowerCase();
  var matches=_contacts.filter(function(c){ return c.name.toLowerCase().indexOf(q)>=0||(c.company||'').toLowerCase().indexOf(q)>=0; });
  if(!matches.length){ drop.style.display='none'; drop.innerHTML=''; return; }
  drop.style.display='block';
  drop.innerHTML=matches.map(function(c){
    var origIdx=_contacts.indexOf(c);
    return '<div class="dl-adresar-item" onmousedown="dlVyplnitKontakt('+origIdx+')">'
      +'<strong>'+c.name+'</strong>'+(c.company?' <span style="opacity:.7">· '+c.company+'</span>':'')+(c.ico?' <span style="opacity:.5;font-size:11px">IČO: '+c.ico+'</span>':'')
      +'</div>';
  }).join('');
}
function dlAdresarHide(){ var drop=document.getElementById('dl-adresar-drop'); if(drop){drop.style.display='none';drop.innerHTML='';} }
function dlVyplnitKontakt(idx){
  var c=_contacts[idx]; if(!c) return;
  document.getElementById('dl-f-name').value=c.name||'';
  document.getElementById('dl-f-company').value=c.company||'';
  document.getElementById('dl-f-ico').value=c.ico||'';
  document.getElementById('dl-f-email').value=c.email||'';
  document.getElementById('dl-f-phone').value=c.phone||'';
  document.getElementById('dl-adresar-q').value='';
  dlAdresarHide();
}
function ulozitKontaktDL(){
  var name=document.getElementById('dl-f-name').value.trim();
  if(!name){ alert('Zadejte jméno zákazníka.'); return; }
  var c={ name:name, company:document.getElementById('dl-f-company').value.trim(), ico:document.getElementById('dl-f-ico').value.trim(), email:document.getElementById('dl-f-email').value.trim(), phone:document.getElementById('dl-f-phone').value.trim() };
  var idx=_contacts.findIndex(function(x){ return x.name===name; });
  if(idx>=0){ _contacts[idx]=c; } else { _contacts.push(c); }
  saveContacts();
  var toast=document.createElement('div');
  toast.textContent='✓ Kontakt uložen do adresáře';
  toast.style.cssText='position:fixed;bottom:32px;left:50%;transform:translateX(-50%);background:#4a7a30;color:#fff;padding:12px 28px;border-radius:12px;font-size:15px;font-weight:600;z-index:9999;box-shadow:0 4px 18px rgba(0,0,0,.3);pointer-events:none;transition:opacity .4s';
  document.body.appendChild(toast);
  setTimeout(function(){toast.style.opacity='0';setTimeout(function(){toast.remove();},400);},2000);
}

function openNovyDodaciList(){
  _dlOrder=null; _dlEditId=null;
  _dlItems=[];
  document.getElementById('dl-f-name').value='';
  document.getElementById('dl-f-company').value='';
  document.getElementById('dl-f-ico').value='';
  document.getElementById('dl-f-email').value='';
  document.getElementById('dl-f-phone').value='';
  document.getElementById('dl-f-delivery-date').value='';
  document.getElementById('dl-adresar-q').value='';
  _openDLOverlay();
}

function upravitDL(id, idx){
  var dl=_dodaciListy[idx];
  if(!dl) return;
  _dlEditId=id;
  _dlOrder=null;
  _dlItems=(dl.items||[]).map(function(it){
    var match=P.find(function(p){return p.name===it.name;});
    return Object.assign({},it,{vahy:match?match.vahy:false,voc_kg:match?match.voc_kg:0,vahy_kg:it.vahy_kg||0});
  });
  document.getElementById('dl-f-name').value=dl.customer_name||'';
  document.getElementById('dl-f-company').value=dl.company||'';
  document.getElementById('dl-f-ico').value=dl.ico||'';
  document.getElementById('dl-f-email').value=dl.customer_email||'';
  document.getElementById('dl-f-phone').value=dl.phone||'';
  document.getElementById('dl-f-delivery-date').value=dl.delivery_date||'';
  document.getElementById('dl-adresar-q').value='';
  document.getElementById('dl-note').value=dl.note||'';
  var btn=document.getElementById('dl-save-btn');
  if(btn){btn.textContent='💾 Uložit změny';}
  _dlCatQty={};
  _fillDLKatalog();
  renderDLItems();
  document.getElementById('dl-ov').style.display='block';
}

function closeDodaciList(){
  if(_dlItems.length>0 && !_dlSaved){
    if(confirm('Chcete dodací list uložit před zavřením?')){
      ulozitDL();
      setTimeout(function(){
        document.getElementById('dl-ov').style.display='none'; _dlItems=[]; _dlOrder=null; _dlEditId=null; _dlSaved=false;
      },800);
      return;
    }
  }
  document.getElementById('dl-ov').style.display='none'; _dlItems=[]; _dlOrder=null; _dlEditId=null; _dlSaved=false;
  ['dl-f-name','dl-f-company','dl-f-ico','dl-f-email','dl-f-phone','dl-f-delivery-date','dl-adresar-q'].forEach(function(id){var el=document.getElementById(id);if(el)el.value='';});
  dlAdresarHide();
  var btn=document.getElementById('dl-save-btn');
  if(btn){btn.textContent='💾 Uložit';btn.style.background='#4a7a30';}
}

function _he(s){ return String(s||'').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/"/g,'&quot;'); }

function renderDLItems(){
  var html='<table class="dl-items-tbl"><thead><tr><th>Produkt</th><th>Objem</th><th style="text-align:center">Ks</th><th style="text-align:center">Váha (kg)</th><th style="text-align:right">Cena/jedn.</th><th style="text-align:right">Celkem</th><th></th></tr></thead><tbody>';
  _dlItems.forEach(function(it,i){
    var tot=it.vahy ? (it.vahy_kg||0)*(it.voc_kg||0) : (it.qty||0)*(it.voc||0);
    html+='<tr>'
      +'<td><input class="dl-inp" value="'+_he(it.name)+'" oninput="_dlItems['+i+'].name=this.value">'
        +(it.vahy?'<span class="vahy-badge" style="margin-left:6px;font-size:9px">vážený</span>':'')+'</td>'
      +'<td><input class="dl-inp" value="'+_he(it.baleni||'')+'" oninput="_dlItems['+i+'].baleni=this.value" style="width:72px"></td>'
      +'<td style="text-align:center">'
        +'<div style="display:flex;align-items:center;justify-content:center;gap:4px">'
          +'<button onclick="_dlItems['+i+'].qty=Math.max(0,(_dlItems['+i+'].qty||0)-1);renderDLItems()" style="width:32px;height:32px;border-radius:8px;border:none;background:#503f37;color:#DACBBC;font-size:18px;font-weight:800;cursor:pointer;line-height:1;font-family:Inter,sans-serif">−</button>'
          +'<input class="dl-qty" type="number" min="0" value="'+(it.qty||0)+'" oninput="_dlItems['+i+'].qty=parseInt(this.value)||0;recalcDL()" style="width:46px">'
          +'<button onclick="_dlItems['+i+'].qty=(_dlItems['+i+'].qty||0)+1;renderDLItems()" style="width:32px;height:32px;border-radius:8px;border:none;background:#503f37;color:#DACBBC;font-size:18px;font-weight:800;cursor:pointer;line-height:1;font-family:Inter,sans-serif">+</button>'
        +'</div>'
        +(it.vahy&&(it.vahy_kg||0)>0?'<div style="font-size:10px;color:#4a7a30;font-weight:700;margin-top:2px">'+(it.vahy_kg||0).toFixed(3)+' kg</div>':'')
      +'</td>'
      +'<td style="text-align:center">'+(it.vahy
        ? '<input class="dl-qty" type="number" min="0" step="0.01" value="'+(it.vahy_kg||0)+'" oninput="_dlItems['+i+'].vahy_kg=parseFloat(this.value)||0;recalcDL()" style="width:70px">'
        : '<span style="color:#ccc;font-size:12px">—</span>')+'</td>'
      +'<td style="text-align:right">'+(it.vahy
        ? '<input class="dl-price" type="number" min="0" value="'+(it.voc_kg||0)+'" oninput="_dlItems['+i+'].voc_kg=parseFloat(this.value)||0;recalcDL()"> Kč/kg'
        : '<input class="dl-price" type="number" min="0" value="'+(it.voc||0)+'" oninput="_dlItems['+i+'].voc=parseFloat(this.value)||0;recalcDL()"> Kč/ks')+'</td>'
      +'<td style="text-align:right;font-weight:800;color:#503f37;white-space:nowrap" id="dlr'+i+'">'+tot.toFixed(2)+' Kč</td>'
      +'<td><button class="dl-del" onclick="removeDLItem('+i+')">✕</button></td>'
      +'</tr>';
  });
  html+='</tbody></table>';
  document.getElementById('dl-items-wrap').innerHTML=html;
  recalcDL();
}

function recalcDL(){
  var total=0;
  _dlItems.forEach(function(it,i){
    var val=it.vahy ? (it.vahy_kg||0)*(it.voc_kg||0) : (it.qty||0)*(it.voc||0); total+=val;
    var el=document.getElementById('dlr'+i); if(el) el.textContent=val.toFixed(2)+' Kč';
  });
  document.getElementById('dl-total-val').textContent=fmt(total);
}

function removeDLItem(i){ _dlItems.splice(i,1); renderDLItems(); }

function addDLItem(){
  var n=document.getElementById('dl-new-name').value.trim();
  var v=parseFloat(document.getElementById('dl-new-voc').value)||0;
  if(!n){ alert('Zadejte název položky.'); return; }
  _dlItems.push({name:n,baleni:'',qty:1,voc:v,total:v,vahy:false,voc_kg:0,vahy_kg:0});
  document.getElementById('dl-new-name').value='';
  document.getElementById('dl-new-voc').value='';
  renderDLItems();
}

function _getDLMeta(){
  var tb=_dlItems.reduce(function(s,it){return s+(it.vahy?(it.vahy_kg||0)*(it.voc_kg||0):(it.qty||0)*(it.voc||0));},0);
  var datum=new Date().toLocaleDateString('cs-CZ');
  var dlNum='DL-'+new Date().toISOString().slice(0,10).replace(/-/g,'');
  var note=document.getElementById('dl-note').value.trim();
  var cust={
    name: document.getElementById('dl-f-name').value.trim() || ((_dlOrder&&_dlOrder.customer_name)||'Zákazník'),
    company: document.getElementById('dl-f-company').value.trim(),
    ico: document.getElementById('dl-f-ico').value.trim(),
    email: document.getElementById('dl-f-email').value.trim(),
    phone: document.getElementById('dl-f-phone').value.trim()
  };
  var deliveryDate=document.getElementById('dl-f-delivery-date').value||null;
  return {tb:tb,datum:datum,dlNum:dlNum,note:note,cust:cust,deliveryDate:deliveryDate};
}

function _buildDLHtml(m, items, orderAddr){
  var rows='';
  items.forEach(function(it){
    var tot=it.vahy?(it.vahy_kg||0)*(it.voc_kg||0):(it.qty||0)*(it.voc||0);
    rows+='<tr>'
      +'<td>'+it.name+(it.vahy?' <span style="font-size:10px;color:#4a7a30">⚖ vážený</span>':'')+'</td>'
      +'<td>'+(it.baleni||'—')+'</td>'
      +'<td style="text-align:center">'+(it.qty||0)+' ks</td>'
      +'<td style="text-align:center">'+(it.vahy?(it.vahy_kg||0).toFixed(3)+' kg':'—')+'</td>'
      +'<td style="text-align:right">'+(it.vahy?(it.voc_kg||0).toFixed(2)+' Kč/kg':(it.voc||0).toFixed(2)+' Kč/ks')+'</td>'
      +'<td style="text-align:right;font-weight:800">'+tot.toFixed(2)+' Kč</td>'
      +'</tr>';
  });
  var info='';
  if(m.cust.company) info+='<div>'+m.cust.company+'</div>';
  if(m.cust.ico) info+='<div>IČO: '+m.cust.ico+'</div>';
  if(m.cust.email) info+='<div>'+m.cust.email+'</div>';
  if(m.cust.phone) info+='<div>'+m.cust.phone+'</div>';
  if(orderAddr) info+='<div>'+orderAddr+'</div>';
  var pdfName='DL_'+m.cust.name.replace(/\s+/g,'_')+'_'+new Date().toISOString().slice(0,10);
  return '<!DOCTYPE html><html><head><meta charset="utf-8"><title>'+pdfName+'</title><style>'
    +'*{margin:0;padding:0;box-sizing:border-box;font-family:Arial,sans-serif;}'
    +'body{background:#fff;color:#1e1e1e;padding:20mm 14mm;font-size:9pt;}'
    +'.header{background:#503f37;color:#DACBBC;padding:10px 14px;margin:-20mm -14mm 14mm;display:flex;justify-content:space-between;align-items:center;}'
    +'.header h1{font-size:13pt;font-weight:800;letter-spacing:.03em;}.header small{font-size:7.5pt;opacity:.85;}'
    +'.section-label{font-size:7.5pt;font-weight:800;text-transform:uppercase;letter-spacing:.1em;color:#837261;border-bottom:1px solid #d6cbbf;padding-bottom:3px;margin-bottom:8px;}'
    +'.recipient{margin-bottom:14px;}.recipient .name{font-size:11pt;font-weight:800;margin-bottom:3px;}.recipient div{font-size:8.5pt;color:#503f37;line-height:1.6;}'
    +'table{width:100%;border-collapse:collapse;margin-bottom:10px;}th{background:#503f37;color:#DACBBC;font-size:7.5pt;font-weight:800;padding:5px 7px;text-align:left;}td{padding:5px 7px;font-size:8.5pt;border-bottom:1px solid #e8e0d6;}tr:nth-child(even) td{background:#f5f0ea;}'
    +'.totals{background:#DAC9B8;padding:10px 14px;border-radius:6px;display:flex;flex-direction:column;align-items:flex-end;gap:3px;margin-bottom:14px;}.totals .row{display:flex;gap:40px;font-size:8.5pt;color:#503f37;}.totals .big{font-size:11pt;font-weight:800;color:#1e1e1e;}'
    +'.note{font-size:8pt;color:#837261;font-style:italic;margin-bottom:14px;}'
    +'.sigs{display:flex;justify-content:space-between;margin-top:24px;}.sig{border-top:1px solid #b0a090;padding-top:4px;width:44%;font-size:7.5pt;color:#837261;}'
    +'.footer{position:fixed;bottom:8mm;left:14mm;right:14mm;background:#503f37;color:#DACBBC;text-align:center;font-size:7pt;padding:5px;}@media print{.footer{position:fixed;}}'
    +'</style></head><body>'
    +'<div class="header"><h1>DIVOKÉ FARMY — DODACÍ LIST</h1>'
    +'<div style="text-align:right"><div style="font-size:10pt;font-weight:800">'+m.dlNum+'</div><small>'+m.datum+'</small>'+(m.deliveryDate?'<div style="font-size:7.5pt;color:#DACBBC;opacity:.85;margin-top:2px">Datum doručení: '+new Date(m.deliveryDate+'T12:00:00').toLocaleDateString("cs-CZ")+'</div>':'')+'</div></div>'
    +'<div class="recipient"><div class="section-label">Příjemce</div>'
    +'<div class="name">'+m.cust.name+'</div>'+info+'</div>'
    +'<table><thead><tr><th>Produkt</th><th>Objem</th><th style="text-align:center">Ks</th><th style="text-align:center">Váha (kg)</th><th style="text-align:right">Cena/jedn.</th><th style="text-align:right">Celkem</th></tr></thead><tbody>'+rows+'</tbody></table>'
    +'<div class="totals"><div class="row"><span>Celkem bez DPH:</span><span>'+m.tb.toFixed(2)+' Kč</span></div>'
    +'<div class="row"><span>DPH 12 %:</span><span>'+(m.tb*VAT).toFixed(2)+' Kč</span></div>'
    +'<div class="row big"><span>CELKEM S DPH:</span><span>'+(m.tb*(1+VAT)).toFixed(2)+' Kč</span></div></div>'
    +(m.note?'<div class="note">Poznámka: '+m.note+'</div>':'')
    +'<div class="sigs"><div class="sig">Podpis odesílatele</div><div class="sig">Podpis příjemce</div></div>'
    +'<div class="footer">DF obchodní s.r.o. &nbsp;|&nbsp; IČO: 29279313 &nbsp;|&nbsp; Šebrov 195, 679 22 Lipůvka &nbsp;|&nbsp; divokefarmy.cz</div>'
    +'</body></html>';
}

function stahnoutDL(){
  if(!_dlItems.length){alert('Žádné položky.');return;}
  var m=_getDLMeta();
  var html=_buildDLHtml(m,_dlItems,_dlOrder&&_dlOrder.address?_dlOrder.address:null);
  var blob=new Blob([html],{type:'text/html'});
  var blobUrl=URL.createObjectURL(blob);
  var win=window.open(blobUrl,'_blank','width=850,height=1100');
  win.focus();
  setTimeout(function(){ win.print(); URL.revokeObjectURL(blobUrl); },500);
}

