function stahnoutDLSoubor(){
  if(!_dlItems.length){alert('Žádné položky.');return;}
  var m=_getDLMeta();
  var html=_buildDLHtml(m,_dlItems);
  var pdfName='DL_'+m.cust.name.replace(/\s+/g,'_')+'_'+new Date().toISOString().slice(0,10)+'.html';
  var blob=new Blob([html],{type:'text/html'});
  var a=document.createElement('a');
  a.href=URL.createObjectURL(blob);
  a.download=pdfName;
  document.body.appendChild(a);
  a.click();
  setTimeout(function(){ URL.revokeObjectURL(a.href); a.remove(); },1000);
}

function odeslatDL(){
  if(!_dlItems.length){alert('Žádné položky.');return;}
  var m=_getDLMeta();
  if(!m.cust.name){alert('Zadejte prosím jméno zákazníka.');return;}
  stahnoutDL();
  _db.from('delivery_notes').insert([{
    order_id:_dlOrder?_dlOrder.id:null,
    customer_name:m.cust.name,
    customer_email:m.cust.email||null,
    company:m.cust.company||null,
    phone:m.cust.phone||null,
    items:_dlItems.map(function(it){return{name:it.name,baleni:it.baleni||'',qty:it.qty||0,voc:it.voc||0,total:(it.qty||0)*(it.voc||0)};}),
    total_without_vat:m.tb, note:m.note||null
  }]).then(function(res){if(res.error)console.warn('DL save:',res.error.message);});
  if(!m.cust.email){return;}
  var subj='Dodací list '+m.dlNum+' – '+m.cust.name;
  var body='Dobrý den,\n\npřikládáme dodací list '+m.dlNum+' ze dne '+m.datum+'.\n\nCelkem bez DPH: '+m.tb.toFixed(2)+' Kč\nCelkem s DPH: '+(m.tb*(1+VAT)).toFixed(2)+' Kč\n\nS pozdravem\nDivoké Farmy';
  setTimeout(function(){
    window.location.href='mailto:'+encodeURIComponent(m.cust.email)+'?subject='+encodeURIComponent(subj)+'&body='+encodeURIComponent(body);
  },800);
}

function ulozitDL(){
  if(!_dlItems.length){alert('Žádné položky.');return;}
  var m=_getDLMeta();
  if(!m.cust.name){alert('Zadejte prosím jméno zákazníka.');return;}
  var btn=document.getElementById('dl-save-btn');
  if(btn){btn.disabled=true;btn.textContent='Ukládám…';}
  var data={
    customer_name:m.cust.name,
    customer_email:m.cust.email||null,
    company:m.cust.company||null,
    ico:m.cust.ico||null,
    phone:m.cust.phone||null,
    delivery_date:m.deliveryDate||null,
    items:_dlItems.map(function(it){return{name:it.name,baleni:it.baleni||'',qty:it.qty||0,voc:it.voc||0,vahy:it.vahy||false,voc_kg:it.voc_kg||0,vahy_kg:it.vahy_kg||0,total:(it.vahy?(it.vahy_kg||0)*(it.voc_kg||0):(it.qty||0)*(it.voc||0))};}),
    total_without_vat:m.tb, note:m.note||null
  };
  var req;
  if(_dlEditId){
    req=_db.from('delivery_notes').update(data).eq('id',_dlEditId);
  } else {
    data.order_id=_dlOrder?_dlOrder.id:null;
    req=_db.from('delivery_notes').insert([data]);
  }
  req.then(function(res){
    if(btn){btn.disabled=false;}
    if(res.error){alert('Chyba při ukládání: '+res.error.message);return;}
    _dlSaved=true;
    btn.textContent='✓ Uloženo';
    btn.style.background='#2d5a1b';
    setTimeout(function(){if(btn){btn.textContent=_dlEditId?'💾 Uložit změny':'💾 Uložit';btn.style.background='#4a7a30';}},2500);
    var toast=document.createElement('div');
    toast.textContent='✓ Dodací list byl uložen';
    toast.style.cssText='position:fixed;bottom:32px;left:50%;transform:translateX(-50%);background:#2d5a1b;color:#fff;padding:12px 28px;border-radius:12px;font-size:15px;font-weight:600;z-index:9999;box-shadow:0 4px 18px rgba(0,0,0,.3);pointer-events:none;transition:opacity .4s';
    document.body.appendChild(toast);
    setTimeout(function(){toast.style.opacity='0';setTimeout(function(){toast.remove();},400);},2000);
  });
}

var _dodaciListy=[];
function loadDodaciListy(){
  document.getElementById('dl-list').innerHTML='<div class="orders-msg">Načítám dodací listy…</div>';
  _db.from('delivery_notes').select('*').order('created_at',{ascending:false}).then(function(res){
    if(res.error){document.getElementById('dl-list').innerHTML='<div class="orders-msg">Chyba: '+res.error.message+'</div>';return;}
    _dodaciListy=res.data||[]; renderDodaciListy();
  });
}
function renderDodaciListy(){
  var list=document.getElementById('dl-list');
  if(!_dodaciListy.length){list.innerHTML='<div class="orders-msg">Zatím žádné dodací listy.</div>';return;}
  var archivedIds;
  try{ archivedIds=JSON.parse(localStorage.getItem('df_dl_arch')||'[]'); }catch(e){ archivedIds=[]; }
  var html='<div class="orders-list">';
  _dodaciListy.forEach(function(dl,idx){
    var d=new Date(dl.created_at).toLocaleDateString('cs-CZ');
    var items=dl.items||[];
    var isArch=archivedIds.indexOf(dl.id)>=0;
    var dlStatus=dl.status||'odeslano';
    var isVyrizena=dlStatus==='vyrizeno';
    var irows=items.map(function(it){
      var qty=(it.qty||0)+' ks'+(it.vahy&&it.vahy_kg?'<br><span style="font-size:10px;color:#4a7a30;font-weight:700">'+parseFloat(it.vahy_kg).toFixed(3)+' kg</span>':'');
      return'<tr><td>'+(it.name||'')+(it.baleni?' ('+it.baleni+')':'')+'</td><td style="text-align:center">'+qty+'</td><td style="text-align:right;font-weight:800">'+(it.total||0).toFixed(2)+' Kč</td></tr>';
    }).join('');
    var statusBadge=isArch
      ?'<span class="order-status st-archivovana">Archivováno</span>'
      :(isVyrizena
        ?'<span class="st-dl-vyrizena" id="dlstlbl'+idx+'">✓ Vyřízeno</span>'
        :'<span class="st-dl-odeslano" id="dlstlbl'+idx+'">Odesláno</span>');
    var deliveryDateStr=dl.delivery_date?new Date(dl.delivery_date+'T12:00:00').toLocaleDateString('cs-CZ'):'';
    html+='<div class="order-card'+(isArch?' storno-card':'')+(isVyrizena?' dl-card-vyrizena':'')+'" id="dlc'+idx+'">'
      +'<div class="order-hd" onclick="this.nextElementSibling.classList.toggle(\'show\')">'
      +'<span class="order-date">'+(deliveryDateStr?deliveryDateStr:d)+'</span>'
      +'<span class="order-name">'+(dl.customer_name||'')+(dl.company?'<br><small style="font-size:11px;font-weight:500;opacity:.65">'+dl.company+'</small>':'')+'</span>'
      +'<span class="order-total">'+(dl.total_without_vat||0).toFixed(2)+' Kč</span>'
      +statusBadge
      +'</div>'
      +'<div class="order-body">'
      +'<div class="order-info">'+(dl.ico?'IČO: '+dl.ico+' · ':'')+''+(dl.customer_email?dl.customer_email:'')+(dl.phone?' · '+dl.phone:'')+'</div>'
      +'<table class="order-items-tbl"><tr><th>Produkt</th><th style="text-align:center">Množství</th><th style="text-align:right">Celkem</th></tr>'+irows+'</table>'
      +'<div class="order-actions">'
      +'<button class="order-pdf-btn" onclick="tiskniUlozeneDLPDF('+idx+')">🖨 PDF / Tisk</button>'
      +(isArch?'':(!isVyrizena
        ?'<button class="muted-btn" style="background:rgba(74,122,48,0.12);color:#2d5a1b;border-color:rgba(74,122,48,0.3)" onclick="setDLStatus(\''+dl.id+'\','+idx+',\'vyrizeno\')">✓ Označit vyřízeno</button>'
        :'<button class="muted-btn" onclick="setDLStatus(\''+dl.id+'\','+idx+',\'odeslano\')">↩ Odznačit</button>'))
      +'<button class="muted-btn" onclick="upravitDL(\''+dl.id+'\','+idx+')">✎ Upravit</button>'
      +'<button class="muted-btn" onclick="archivujDL(\''+dl.id+'\','+idx+')">'+(isArch?'↩ Obnovit':'📦 Archivovat')+'</button>'
      +'<button class="danger-btn" style="border-color:rgba(100,0,0,0.3);background:rgba(100,0,0,0.07);color:#800" onclick="smazatDL(\''+dl.id+'\','+idx+')">🗑 Smazat</button>'
      +'</div>'
      +'</div></div>';
  });
  html+='</div>'; list.innerHTML=html;
}
function archivujDL(id,idx){
  try{
    var arch=JSON.parse(localStorage.getItem('df_dl_arch')||'[]');
    var pos=arch.indexOf(id);
    if(pos>=0) arch.splice(pos,1); else arch.push(id);
    localStorage.setItem('df_dl_arch',JSON.stringify(arch));
  }catch(e){}
  renderDodaciListy();
}
function setDLStatus(id,idx,status){
  _db.from('delivery_notes').update({status:status}).eq('id',id).then(function(res){
    if(res.error){ alert('Chyba: '+res.error.message+'\n\nPotřebuješ přidat sloupec:\nALTER TABLE delivery_notes ADD COLUMN IF NOT EXISTS status TEXT DEFAULT \'odeslano\';'); return; }
    if(_dodaciListy[idx]) _dodaciListy[idx].status=status;
    renderDodaciListy();
  });
}
function smazatDL(id,idx){
  if(!confirm('Opravdu trvale smazat tento dodací list? Tato akce je nevratná.')) return;
  _db.from('delivery_notes').delete().eq('id',id).then(function(res){
    if(res.error){ alert('Chyba při mazání: '+res.error.message+'\n\nPravděpodobně chybí SQL politika — spusť v Supabase:\nCREATE POLICY "admin_delete_delivery_notes" ON delivery_notes FOR DELETE TO authenticated USING (true);'); return; }
    _dodaciListy=_dodaciListy.filter(function(dl){ return dl.id!==id; });
    renderDodaciListy();
  });
}

// ── Customer Auth ──
var _user = null;

function _onAuthChange(user){
  _user = user;
  var guest = document.getElementById('auth-bar-guest');
  var loggedIn = document.getElementById('auth-bar-user');
  var lbl = document.getElementById('auth-email-lbl');
  var adminLink = document.getElementById('auth-admin-link');
  if(user){
    if(guest) guest.style.display='none';
    if(loggedIn) loggedIn.style.display='flex';
    if(lbl) lbl.textContent = user.email;
    if(adminLink) adminLink.style.display = _isAdmin() ? 'inline' : 'none';
    _prefillFromLastOrder(user.id);
    if(_adminPendingOpen){
      _adminPendingOpen = false;
      if(_isAdmin()) openAdmin();
      else alert('Tento účet nemá administrátorská oprávnění.');
    }
  } else {
    if(guest) guest.style.display='flex';
    if(loggedIn) loggedIn.style.display='none';
  }
}

function openAuthModal(tab){
  document.getElementById('auth-ov').className='show';
  document.getElementById('auth-err').textContent='';
  document.getElementById('auth-email').value='';
  document.getElementById('auth-pw').value='';
  switchAuthTab(tab||'login');
  setTimeout(function(){ document.getElementById('auth-email').focus(); },80);
}
function closeAuthModal(){ document.getElementById('auth-ov').className=''; }

function switchAuthTab(tab){
  var isLogin=tab==='login';
  document.getElementById('tab-login').classList.toggle('act',isLogin);
  document.getElementById('tab-register').classList.toggle('act',!isLogin);
  document.getElementById('auth-submit-btn').textContent=isLogin?'Přihlásit se':'Registrovat';
  document.getElementById('auth-ov').dataset.tab=tab;
}

function doAuthSubmit(){
  var email=document.getElementById('auth-email').value.trim();
  var pw=document.getElementById('auth-pw').value;
  var err=document.getElementById('auth-err');
  var tab=document.getElementById('auth-ov').dataset.tab||'login';
  if(!email||!pw){ err.textContent='Vyplňte e-mail a heslo.'; return; }
  if(pw.length<6){ err.textContent='Heslo musí mít alespoň 6 znaků.'; return; }
  var btn=document.getElementById('auth-submit-btn');
  btn.disabled=true; btn.textContent='Načítám…';
  var p=tab==='login'
    ? _db.auth.signInWithPassword({email:email,password:pw})
    : _db.auth.signUp({email:email,password:pw});
  p.then(function(res){
    btn.disabled=false; btn.textContent=tab==='login'?'Přihlásit se':'Registrovat';
    if(res.error){ err.textContent=res.error.message; return; }
    closeAuthModal();
    if(tab==='register') alert('Registrace proběhla úspěšně! Jste přihlášeni.');
  });
}

function doLogout(){
  _db.auth.signOut();
}

function openMyOrders(){
  document.getElementById('myord-ov').className='show';
  loadMyOrders();
}
function closeMyOrders(){ document.getElementById('myord-ov').className=''; }

function loadMyOrders(){
  if(!_user) return;
  var list=document.getElementById('myord-list');
  list.innerHTML='<div class="orders-msg">Načítám…</div>';
  _db.from('orders').select('*').eq('user_id',_user.id).order('created_at',{ascending:false}).then(function(res){
    if(res.error){ list.innerHTML='<div class="orders-msg">Chyba: '+res.error.message+'</div>'; return; }
    var orders=res.data||[];
    if(!orders.length){ list.innerHTML='<div class="orders-msg">Zatím žádné objednávky.</div>'; return; }
    var stLabel={nova:'Nová',vyrizuje_se:'Vyřizuje se',vyrizena:'Vyřízena',storno:'Storno',archivovana:'Archivováno'};
    var stCls={nova:'st-nova',vyrizuje_se:'st-vyrizuje',vyrizena:'st-vyrizena',storno:'st-storno',archivovana:'st-archivovana'};
    var html='<div class="orders-list">';
    orders.forEach(function(o){
      var d=new Date(o.created_at).toLocaleDateString('cs-CZ');
      var st=o.status||'nova';
      var items=o.items||[];
      var irows=items.map(function(it){
        return '<tr><td>'+(it.name||'')+(it.baleni?' ('+it.baleni+')':'')+'</td>'
          +'<td style="text-align:center">'+it.qty+' ks</td>'
          +'<td style="text-align:right;font-weight:800">'+it.total.toFixed(2)+' Kč</td></tr>';
      }).join('');
      html+='<div class="order-card">'
        +'<div class="order-hd" onclick="this.nextElementSibling.classList.toggle(\'show\')">'
        +'<span class="order-date">'+d+'</span>'
        +'<span class="order-total">'+o.total_without_vat.toFixed(2)+' Kč</span>'
        +'<span class="order-status '+(stCls[st]||'st-nova')+'">'+(stLabel[st]||'Nová')+'</span>'
        +'</div>'
        +'<div class="order-body">'
        +'<table class="order-items-tbl"><tr><th>Produkt</th><th style="text-align:center">Množství</th><th style="text-align:right">Celkem</th></tr>'+irows+'</table>'
        +'</div></div>';
    });
    html+='</div>';
    list.innerHTML=html;
  });
}

function _prefillFromLastOrder(userId){
  var jmeno=document.getElementById('jmeno');
  if(jmeno&&jmeno.value.trim()) return;
  _db.from('orders').select('customer_name,company,email,phone,address').eq('user_id',userId).order('created_at',{ascending:false}).limit(1).then(function(res){
    if(res.error||!res.data||!res.data.length) return;
    var o=res.data[0];
    var map={jmeno:'customer_name',firma:'company',email:'email',tel:'phone',adr:'address'};
    Object.keys(map).forEach(function(id){
      var el=document.getElementById(id);
      if(el&&!el.value.trim()&&o[map[id]]) el.value=o[map[id]];
    });
  });
}

// Init auth state
_db.auth.getUser().then(function(res){ if(res.data&&res.data.user) _onAuthChange(res.data.user); });
_db.auth.onAuthStateChange(function(event,session){ _onAuthChange(session?session.user:null); });

// Auth modal keyboard
document.getElementById('auth-pw').addEventListener('keydown',function(e){ if(e.key==='Enter') doAuthSubmit(); });

function toggleTheme(){
  var light=document.body.classList.toggle('light');
  localStorage.setItem('df_theme',light?'light':'dark');
  document.getElementById('btn-theme').textContent=light?'🌙':'☀';
}

