// Remember-me autofill
(function(){
  try{
    var saved=localStorage.getItem('df_customer');
    if(saved){
      var c=JSON.parse(saved);
      ['jmeno','firma','email','tel','adr'].forEach(function(id){ var el=document.getElementById(id); if(el&&c[id]) el.value=c[id]; });
      document.getElementById('remember-me').checked=true;
      document.getElementById('forget-link').style.display='inline';
    }
  }catch(e){}
})();

