loadContacts();
_db.from('product_state').select('*').eq('id',1).single().then(function(res){
  if(!res.error && res.data){
    _applyState(res.data);
  } else {
    try{ var s=localStorage.getItem('df_av'); if(s) Object.assign(avail,JSON.parse(s)); }catch(e){}
    try{ var po=localStorage.getItem('df_po'); if(po){ prodOverrides=JSON.parse(po); Object.keys(prodOverrides).forEach(function(i){ if(P[i]) Object.assign(P[i],prodOverrides[i]); }); } }catch(e){}
    try{ var ar=localStorage.getItem('df_arch'); if(ar) archived=JSON.parse(ar); }catch(e){}
    try{ var dl=localStorage.getItem('df_del'); if(dl) deleted=JSON.parse(dl); }catch(e){}
    try{ var cp=localStorage.getItem('df_cp'); if(cp){ customProds=JSON.parse(cp); customProds.forEach(function(p){ P.push(Object.assign({_custom:true},p)); }); } }catch(e){}
    try{ var po2=localStorage.getItem('df_po'); if(po2){ var po2p=JSON.parse(po2); Object.keys(po2p).forEach(function(i){ if(po2p[i]&&po2p[i].stock>0) stockQty[i]=po2p[i].stock; }); } }catch(e){}
  }
  buildAll();
});

